function checkRateLimit(timestamps: number[], now: number, windowMs: number, maxRequests: number) {
  const recent = timestamps.filter((t) => t > now - windowMs);
  if (recent.length >= maxRequests) {
    return { allowed: false, status: 429, remaining: 0 };
  }
  return { allowed: true, status: 200, remaining: maxRequests - recent.length - 1 };
}
